mkdir -p tmp_t && printf '@include b.conf\n' > tmp_t/a.conf && printf '@include a.conf\n' > tmp_t/b.conf && python -c "
from miniconf.loader import load
for p in ['tmp_t/a.conf','tmp_t/none.conf']:
    try: load(p)
    except Exception as e: print(type(e).__name__, e)"; rm -rf tmp_t

